import { useEffect, useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  Button,
  Badge,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Msg = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null;

const MENU = [
  { value: '1', label: 'Pagar una orden', target: 'SCR-PAGOORD' },
  // Assumption: the spec has no navigation_out; "consultar" is routed to the result screen.
  { value: '2', label: 'Consultar una orden', target: 'SCR-PAGORES' },
];

export default function PagoMenu({ navigate }: { navigate: (to: string) => void }) {
  const [opcion, setOpcion] = useState('');
  const [error, setError] = useState('');
  const [mensaje, setMensaje] = useState<Msg>(null);
  const [exited, setExited] = useState(false);

  const fecha = '15/03/25'; // format 99/99/99

  const continuar = (value: string = opcion) => {
    if (value.trim() === '') {
      setError('Ingrese una opción.');
      setMensaje({ tone: 'error', text: 'Ingrese una opción.' });
      return;
    }
    const item = MENU.find((m) => m.value === value);
    if (!item) {
      setError('Opción inválida. Ingrese 1 o 2.');
      setMensaje({ tone: 'error', text: 'Opción inválida. Ingrese 1 o 2.' });
      return;
    }
    setError('');
    setMensaje({ tone: 'success', text: `Opción ${item.value} seleccionada: ${item.label}.` });
    navigate(item.target);
  };

  const salir = () => {
    setExited(true);
    setError('');
    setMensaje({ tone: 'info', text: 'Sesión finalizada. Puede cerrar esta ventana.' });
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'F3') {
        e.preventDefault();
        setExited(true);
        setError('');
        setMensaje({ tone: 'info', text: 'Sesión finalizada. Puede cerrar esta ventana.' });
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  const volver = () => {
    setExited(false);
    setOpcion('');
    setError('');
    setMensaje(null);
  };

  return (
    <Screen
      title="Banco ficticio - Pagos"
      code="PAGOMEN"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Continuar', onPress: () => !exited && continuar(), primary: true },
            { key: 'PF3', label: 'Salir', onPress: salir },
          ]}
        />
      }
    >
      <Stack>
        <Row>
          <span>Fecha:</span>
          <div data-field="FECHA">
            <Badge>{fecha}</Badge>
          </div>
        </Row>

        <div data-field="MENSAJE" aria-live="polite">
          {mensaje ? <Alert tone={mensaje.tone}>{mensaje.text}</Alert> : null}
        </div>

        {exited ? (
          <Card title="Sesión finalizada">
            <Stack>
              <p>Ha salido del menú de pagos.</p>
              <Button variant="secondary" onClick={volver}>
                Volver al menú
              </Button>
            </Stack>
          </Card>
        ) : (
          <div
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                continuar();
              }
            }}
          >
            <Grid columns={2}>
              <Card title="Operaciones disponibles">
                <Stack>
                  {MENU.map((m) => (
                    <Button
                      key={m.value}
                      variant={opcion === m.value ? 'primary' : 'secondary'}
                      onClick={() => {
                        setOpcion(m.value);
                        setError('');
                        setMensaje(null);
                      }}
                    >
                      {`${m.value}. ${m.label}`}
                    </Button>
                  ))}
                </Stack>
              </Card>

              <Card
                title="Selección"
                actions={
                  <Row>
                    <Button variant="ghost" shortcut="PF3" onClick={salir}>
                      Salir
                    </Button>
                    <Button variant="primary" shortcut="ENTER" onClick={() => continuar()}>
                      Continuar
                    </Button>
                  </Row>
                }
              >
                <div data-field="OPCION">
                  <TextField
                    label="Opción"
                    required
                    numeric
                    maxLength={1}
                    hint="Ingrese 1 para pagar o 2 para consultar una orden."
                    error={error || undefined}
                    value={opcion}
                    onChange={(v: string) => {
                      setOpcion(String(v).replace(/\D/g, '').slice(0, 1));
                      setError('');
                    }}
                  />
                </div>
              </Card>
            </Grid>
          </div>
        )}
      </Stack>
    </Screen>
  );
}
